export const envelope = [64, 52, 64];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 10;
  const cx = 32;
  const cz = 32;

  // -------------------------------------------------------------------------
  // Palette extraction with safe theme roles
  // -------------------------------------------------------------------------
  const woodLog = api.theme.wood.log;
  const woodStripped = api.theme.wood.stripped || api.theme.wood.log;
  const woodPlanks = api.theme.wood.planks;
  const woodStairs = api.theme.wood.stairs;
  const woodSlab = api.theme.wood.slab;
  const woodFence = api.theme.wood.fence;
  const woodTrapdoor = api.theme.wood.trapdoor;

  const stonePrimary = api.theme.stone.primary;
  const stoneWall = api.theme.stone.wall || stonePrimary;
  const stoneStairs = api.theme.stone.stairs || woodStairs;
  const stoneSlab = api.theme.stone.slab || woodSlab;

  const groundPavement = api.theme.ground.pavement || stonePrimary;
  const groundPlinth = api.theme.ground.plinth || woodStripped;

  const roofStairs = api.theme.roof.stairs || woodStairs;
  const roofSlab = api.theme.roof.slab || woodSlab;

  const leaves = "minecraft:acacia_leaves[persistent=true,distance=1]";
  const chain = "minecraft:chain[axis=y]";
  const lanternHang = "minecraft:lantern[hanging=true]";
  const lanternFloor = "minecraft:lantern[hanging=false]";

  // Clean helper for block states
  function clean(b) {
    return b.replace(/\[.*\]/, "");
  }
  const cleanWoodStairs = clean(woodStairs);
  const cleanWoodSlab = clean(woodSlab);
  const cleanRoofStairs = clean(roofStairs);
  const cleanRoofSlab = clean(roofSlab);
  const cleanStoneStairs = clean(stoneStairs);
  const cleanStoneSlab = clean(stoneSlab);

  function stair(base, facing = "north", half = "bottom") {
    return `${base}[facing=${facing},half=${half}]`;
  }
  function slab(base, type = "bottom") {
    return `${base}[type=${type}]`;
  }

  // -------------------------------------------------------------------------
  // 3D Voxel Grid Buffer (Dense Uint16 for fast, deduplicated, bounded writes)
  // -------------------------------------------------------------------------
  const totalVoxels = W * H * D;
  const grid = new Uint16Array(totalVoxels);
  const palette = ["minecraft:air"];
  const paletteMap = new Map([["minecraft:air", 0]]);

  function getBlock(x, y, z) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return 0;
    return grid[x + y * W + z * W * H];
  }

  function setBlock(x, y, z, blockStr) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    let id = paletteMap.get(blockStr);
    if (id === undefined) {
      id = palette.length;
      palette.push(blockStr);
      paletteMap.set(blockStr, id);
    }
    grid[x + y * W + z * W * H] = id;
  }

  function clearBlock(x, y, z) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid[x + y * W + z * W * H] = 0;
  }

  // -------------------------------------------------------------------------
  // Geometry Curves & Shapes
  // -------------------------------------------------------------------------
  const rootAngles = [
    0.0,
    Math.PI / 3,
    (2 * Math.PI) / 3,
    Math.PI,
    (-2 * Math.PI) / 3,
    -Math.PI / 3,
  ];

  function getTrunkProfile(y, angle) {
    let rootInfluence = 0;
    for (let i = 0; i < rootAngles.length; i++) {
      let da = Math.abs(angle - rootAngles[i]);
      if (da > Math.PI) da = 2 * Math.PI - da;
      const inf = Math.max(0, Math.cos(da * 3));
      if (inf > rootInfluence) rootInfluence = inf;
    }

    let rProf = 13.0;
    if (y < 10) {
      rProf = 13.0 + (10 - y) * 0.45 + rootInfluence * (10 - y) * 1.1;
    } else if (y <= 16) {
      rProf = 13.0 + (y - 10) * 0.25 + rootInfluence * (16 - y) * 0.4;
    } else if (y <= 26) {
      rProf = 14.5 - (y - 16) * 0.12;
    } else if (y <= 35) {
      rProf = 13.3 - (y - 26) * 0.22;
    } else {
      rProf = 11.3 - (y - 35) * 0.4;
    }

    const fluting =
      1.0 + 0.08 * Math.cos(6 * angle) + 0.03 * Math.sin(12 * angle);
    const rOut = rProf * fluting;
    const rIn = y >= 10 && y <= 32 ? Math.max(0, rProf - 2.6) : -1;

    return { rOut, rIn, rProf, rootInfluence };
  }

  // -------------------------------------------------------------------------
  // 1. Build Base Trunk & Ground-Conforming Roots
  // -------------------------------------------------------------------------
  for (let z = 0; z < D; z++) {
    for (let x = 0; x < W; x++) {
      const dx = x - cx;
      const dz = z - cz;
      const r = Math.sqrt(dx * dx + dz * dz);
      if (r > 25) continue;

      const angle = Math.atan2(dz, dx);
      const gh = api.heightAt(x, z);
      const groundY = Math.max(0, seatY + gh);

      for (let y = groundY; y <= 36; y++) {
        const { rOut, rIn } = getTrunkProfile(y, angle);

        if (r <= rOut) {
          if (rIn > 0 && r < rIn) {
            // Inside hollow chamber (handled in interior phase)
            continue;
          }

          // Bark or solid wood
          const isOuter = r > rOut - 1.3;
          const isGroove = Math.cos(6 * angle) < -0.15;

          if (isOuter && isGroove) {
            setBlock(x, y, z, woodStripped);
          } else if (isOuter) {
            setBlock(x, y, z, woodLog);
          } else {
            setBlock(x, y, z, woodStripped);
          }
        }
      }

      // Fill solid foundation/roots down to groundY if ground fell away
      if (groundY < seatY) {
        const { rOut } = getTrunkProfile(seatY, angle);
        if (r <= rOut) {
          for (let y = groundY; y < seatY; y++) {
            setBlock(x, y, z, r < 8 ? groundPlinth : woodLog);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // 2. Grand Portals, Windows & Approach Stairs
  // -------------------------------------------------------------------------
  // North Entrance (Facing -Z / Front)
  for (let y = seatY; y <= seatY + 5; y++) {
    for (let x = cx - 3; x <= cx + 3; x++) {
      for (let z = cz - 16; z <= cz - 9; z++) {
        clearBlock(x, y, z);
      }
    }
  }
  // Archway frame North
  for (let y = seatY; y <= seatY + 5; y++) {
    setBlock(cx - 3, y, cz - 14, woodLog);
    setBlock(cx + 3, y, cz - 14, woodLog);
  }
  setBlock(cx - 3, seatY + 6, cz - 14, stair(cleanWoodStairs, "east", "top"));
  setBlock(cx + 3, seatY + 6, cz - 14, stair(cleanWoodStairs, "west", "top"));
  for (let x = cx - 2; x <= cx + 2; x++) {
    setBlock(x, seatY + 6, cz - 14, woodLog);
  }
  setBlock(cx - 2, seatY + 5, cz - 14, stair(cleanWoodStairs, "east", "top"));
  setBlock(cx + 2, seatY + 5, cz - 14, stair(cleanWoodStairs, "west", "top"));

  // South, East, West Archways
  const sideArches = [
    { name: "south", dx: 0, dz: 13, facing: "south" },
    { name: "east", dx: 13, dz: 0, facing: "east" },
    { name: "west", dx: -13, dz: 0, facing: "west" },
  ];
  for (const arch of sideArches) {
    const ax = cx + arch.dx;
    const az = cz + arch.dz;
    for (let y = seatY; y <= seatY + 4; y++) {
      for (let ox = -2; ox <= 2; ox++) {
        for (let oz = -2; oz <= 2; oz++) {
          const px = ax + ox;
          const pz = az + oz;
          const dist = Math.sqrt((px - cx) ** 2 + (pz - cz) ** 2);
          if (dist >= 9 && dist <= 16) {
            clearBlock(px, y, pz);
          }
        }
      }
    }
  }

  // Windows / Balcony Openings
  for (let y = 20; y <= 22; y++) {
    for (let x = cx - 2; x <= cx + 2; x++) {
      clearBlock(x, y, cz - 14); // North high window
      clearBlock(x, y, cz + 14); // South high window
    }
    for (let z = cz - 2; z <= cz + 2; z++) {
      clearBlock(cx + 14, y, z); // East high window
      clearBlock(cx - 14, y, z); // West high window
    }
  }

  // Conforming Entrance Steps descending from seatY to groundY
  const aprons = [
    { minX: cx - 4, maxX: cx + 4, minZ: cz - 20, maxZ: cz - 12 },
    { minX: cx - 4, maxX: cx + 4, minZ: cz + 12, maxZ: cz + 20 },
    { minX: cx + 12, maxX: cx + 20, minZ: cz - 4, maxZ: cz + 4 },
    { minX: cx - 20, maxX: cx - 12, minZ: cz - 4, maxZ: cz + 4 },
  ];

  for (const apr of aprons) {
    for (let z = apr.minZ; z <= apr.maxZ; z++) {
      for (let x = apr.minX; x <= apr.maxX; x++) {
        const gh = api.heightAt(x, z);
        const groundY = Math.max(0, seatY + gh);
        for (let y = groundY; y <= seatY; y++) {
          if (y === seatY) {
            setBlock(x, y, z, groundPavement);
          } else {
            setBlock(x, y, z, stonePrimary);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // 3. Hollow Interior Multi-Tiered Market
  // -------------------------------------------------------------------------
  // Tier 1: Ground Floor Market Hall (y = seatY)
  for (let z = cz - 11; z <= cz + 11; z++) {
    for (let x = cx - 11; x <= cx + 11; x++) {
      const dx = x - cx;
      const dz = z - cz;
      const r = Math.sqrt(dx * dx + dz * dz);
      const { rIn } = getTrunkProfile(seatY, Math.atan2(dz, dx));

      if (r <= rIn) {
        // Patterned floor
        if (r < 2.5) {
          setBlock(x, seatY, z, groundPlinth);
        } else if (Math.abs(dx) === Math.abs(dz) || dx === 0 || dz === 0) {
          setBlock(x, seatY, z, groundPavement);
        } else {
          setBlock(x, seatY, z, woodPlanks);
        }

        // Clear air for market hall
        for (let y = seatY + 1; y <= seatY + 7; y++) {
          clearBlock(x, y, z);
        }
      }
    }
  }

  // Central Timber Pillar & Chandelier
  for (let y = seatY + 1; y <= 28; y++) {
    setBlock(cx - 1, y, cz - 1, woodStripped);
    setBlock(cx, y, cz - 1, woodStripped);
    setBlock(cx - 1, y, cz, woodStripped);
    setBlock(cx, y, cz, woodStripped);
  }
  // Base plinth around central pillar
  for (let ox = -2; ox <= 1; ox++) {
    for (let oz = -2; oz <= 1; oz++) {
      if (ox === -2 || ox === 1 || oz === -2 || oz === 1) {
        setBlock(cx + ox, seatY + 1, cz + oz, slab(cleanWoodSlab, "bottom"));
      }
    }
  }
  // Ground Tier Market Stalls (Alcoves)
  const stallPositions = [
    { x: cx + 6, z: cz - 6, fDir: "west" },
    { x: cx + 7, z: cz + 2, fDir: "west" },
    { x: cx + 4, z: cz + 7, fDir: "north" },
    { x: cx - 6, z: cz + 6, fDir: "east" },
    { x: cx - 7, z: cz - 2, fDir: "east" },
    { x: cx - 4, z: cz - 7, fDir: "south" },
  ];
  for (const st of stallPositions) {
    setBlock(st.x, seatY + 1, st.z, woodPlanks);
    setBlock(
      st.x + 1,
      seatY + 1,
      st.z,
      stair(cleanWoodStairs, st.fDir, "bottom"),
    );
    setBlock(
      st.x - 1,
      seatY + 1,
      st.z,
      stair(cleanWoodStairs, st.fDir, "bottom"),
    );
    setBlock(st.x - 1, seatY + 2, st.z, woodFence);
    setBlock(st.x + 1, seatY + 2, st.z, woodFence);
    setBlock(st.x - 1, seatY + 3, st.z, woodFence);
    setBlock(st.x + 1, seatY + 3, st.z, woodFence);
    setBlock(st.x - 1, seatY + 4, st.z, slab(cleanWoodSlab, "top"));
    setBlock(st.x, seatY + 4, st.z, slab(cleanWoodSlab, "top"));
    setBlock(st.x + 1, seatY + 4, st.z, slab(cleanWoodSlab, "top"));
    setBlock(st.x, seatY + 3, st.z, lanternHang);
  }

  // Spiral Stair Hugging Bark (Ground y=10 to Mezzanine y=18)
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const ang = 0.5 + t * 1.8 * Math.PI;
    const sy = seatY + Math.floor(t * 8);
    const { rIn } = getTrunkProfile(sy, ang);
    const sr = rIn - 1.1;
    const sx = Math.round(cx + sr * Math.cos(ang));
    const sz = Math.round(cz + sr * Math.sin(ang));

    setBlock(sx, sy, sz, woodPlanks);
    setBlock(sx, sy + 1, sz, woodFence);
    for (let y = sy + 1; y <= sy + 3; y++) {
      clearBlock(sx, y, sz);
    }
  }

  // Tier 2: Mezzanine Balcony Ring (y = 18)
  for (let z = cz - 11; z <= cz + 11; z++) {
    for (let x = cx - 11; x <= cx + 11; x++) {
      const dx = x - cx;
      const dz = z - cz;
      const r = Math.sqrt(dx * dx + dz * dz);
      const { rIn } = getTrunkProfile(18, Math.atan2(dz, dx));

      if (r <= rIn && r >= 5.2) {
        setBlock(x, 18, z, woodPlanks);
        for (let y = 19; y <= 25; y++) {
          clearBlock(x, y, z);
        }
        if (r < 6.2) {
          setBlock(x, 19, z, woodFence);
        }
      }
    }
  }

  // Spiral Stair 2 (Mezzanine y=18 to Loft y=26)
  for (let i = 0; i <= 22; i++) {
    const t = i / 22;
    const ang = 2.4 + t * 1.7 * Math.PI;
    const sy = 18 + Math.floor(t * 8);
    const { rIn } = getTrunkProfile(sy, ang);
    const sr = rIn - 1.1;
    const sx = Math.round(cx + sr * Math.cos(ang));
    const sz = Math.round(cz + sr * Math.sin(ang));

    setBlock(sx, sy, sz, woodPlanks);
    setBlock(sx, sy + 1, sz, woodFence);
    for (let y = sy + 1; y <= sy + 3; y++) {
      clearBlock(sx, y, sz);
    }
  }

  // Tier 3: Upper Loft Timber Bridge (y = 26)
  for (let z = cz - 9; z <= cz + 9; z++) {
    for (let x = cx - 2; x <= cx + 2; x++) {
      setBlock(x, 26, z, woodPlanks);
      if (x === cx - 2 || x === cx + 2) {
        setBlock(x, 27, z, woodFence);
      }
      for (let y = 27; y <= 32; y++) {
        if (x !== cx - 2 && x !== cx + 2) clearBlock(x, y, z);
      }
    }
  }

  // Central Chandelier hanging from upper hollow dome
  for (let y = 25; y >= 15; y--) {
    setBlock(cx, y, cz - 2, chain);
  }
  setBlock(cx, 14, cz - 2, woodPlanks);
  setBlock(cx + 1, 14, cz - 2, woodFence);
  setBlock(cx - 1, 14, cz - 2, woodFence);
  setBlock(cx, 14, cz - 1, woodFence);
  setBlock(cx, 14, cz - 3, woodFence);
  setBlock(cx + 1, 13, cz - 2, lanternHang);
  setBlock(cx - 1, 13, cz - 2, lanternHang);
  setBlock(cx, 13, cz - 1, lanternHang);
  setBlock(cx, 13, cz - 3, lanternHang);

  // -------------------------------------------------------------------------
  // 4. Exterior Spiral Walkway Climbing Bark
  // -------------------------------------------------------------------------
  for (let i = 0; i <= 44; i++) {
    const t = i / 44;
    const ang = 0.2 + t * 3.2 * Math.PI;
    const wy = 11 + Math.floor(t * 22);
    const { rOut } = getTrunkProfile(wy, ang);

    for (let dr = 0.6; dr <= 2.2; dr += 0.8) {
      const rx = Math.round(cx + (rOut + dr) * Math.cos(ang));
      const rz = Math.round(cz + (rOut + dr) * Math.sin(ang));
      setBlock(rx, wy, rz, woodPlanks);
      clearBlock(rx, wy + 1, rz);
      clearBlock(rx, wy + 2, rz);
      clearBlock(rx, wy + 3, rz);

      // Support strut under walkway
      if (dr > 1.8) {
        setBlock(rx, wy + 1, rz, woodFence);
        setBlock(
          rx,
          wy - 1,
          rz,
          stair(
            cleanWoodStairs,
            Math.cos(ang) > 0 ? "west" : "east",
            "top",
          ),
        );
      }
    }
    // Lanterns periodically on exterior path
    if (i % 9 === 0) {
      const fx = Math.round(cx + (rOut + 2.4) * Math.cos(ang));
      const fz = Math.round(cz + (rOut + 2.4) * Math.sin(ang));
      setBlock(fx, wy + 1, fz, woodFence);
      setBlock(fx, wy + 2, fz, lanternFloor);
    }
  }

  // -------------------------------------------------------------------------
  // 5. Massive Horizontal Boughs (Quadratic Bezier 3D Splines)
  // -------------------------------------------------------------------------
  function drawBranch(p0, p1, p2, r0, r1) {
    const steps = 28;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const it = 1 - t;
      const bx = it * it * p0[0] + 2 * it * t * p1[0] + t * t * p2[0];
      const by = it * it * p0[1] + 2 * it * t * p1[1] + t * t * p2[1];
      const bz = it * it * p0[2] + 2 * it * t * p1[2] + t * t * p2[2];
      const br = (1 - t) * r0 + t * r1;
      const ceilR = Math.ceil(br);

      for (let dy = -ceilR; dy <= ceilR; dy++) {
        for (let dz = -ceilR; dz <= ceilR; dz++) {
          for (let dx = -ceilR; dx <= ceilR; dx++) {
            if (dx * dx + dy * dy + dz * dz <= br * br) {
              const px = Math.round(bx + dx);
              const py = Math.round(by + dy);
              const pz = Math.round(bz + dz);
              if (py < H && py >= 0) {
                setBlock(
                  px,
                  py,
                  pz,
                  Math.abs(dx) + Math.abs(dz) > br * 0.8
                    ? woodLog
                    : woodStripped,
                );
              }
            }
          }
        }
      }
    }
  }

  // 4 Major Boughs
  // North-East Bough
  drawBranch([32, 34, 32], [42, 37, 24], [52, 40, 16], 3.8, 2.2);
  drawBranch([44, 38, 22], [52, 41, 18], [58, 43, 20], 2.2, 1.4);
  drawBranch([46, 39, 20], [47, 42, 14], [48, 45, 10], 2.0, 1.3);

  // South-East Bough
  drawBranch([32, 34, 32], [44, 36, 42], [53, 38, 50], 3.8, 2.2);
  drawBranch([45, 37, 43], [52, 40, 44], [57, 41, 44], 2.2, 1.4);
  drawBranch([48, 38, 46], [49, 41, 52], [50, 43, 56], 2.0, 1.3);

  // South-West Bough
  drawBranch([32, 34, 32], [20, 37, 44], [13, 39, 50], 3.8, 2.2);
  drawBranch([21, 38, 43], [15, 41, 44], [10, 43, 44], 2.2, 1.4);
  drawBranch([18, 38, 46], [17, 41, 52], [16, 44, 57], 2.0, 1.3);

  // North-West Bough
  drawBranch([32, 34, 32], [20, 36, 22], [12, 38, 14], 3.8, 2.2);
  drawBranch([22, 37, 21], [15, 40, 22], [10, 42, 22], 2.2, 1.4);
  drawBranch([18, 37, 18], [17, 41, 12], [16, 43, 8], 2.0, 1.3);

  // Central Crown Trunk
  drawBranch([32, 34, 32], [32, 41, 32], [32, 47, 32], 4.2, 2.6);
  drawBranch([32, 45, 32], [30, 47, 30], [28, 49, 28], 2.0, 1.2);
  drawBranch([32, 45, 32], [34, 47, 30], [36, 49, 28], 2.0, 1.2);
  drawBranch([32, 45, 32], [34, 47, 34], [36, 49, 36], 2.0, 1.2);
  drawBranch([32, 45, 32], [30, 47, 34], [28, 49, 36], 2.0, 1.2);

  // -------------------------------------------------------------------------
  // 6. Canopy Foliage Umbrella Pads (Acacia/Baobab flat pads)
  // -------------------------------------------------------------------------
  function drawFoliagePad(cx, cy, cz, rx, ry, rz) {
    const rx2 = rx * rx;
    const ry2 = ry * ry;
    const rz2 = rz * rz;

    for (let dy = -Math.ceil(ry); dy <= Math.ceil(ry); dy++) {
      for (let dz = -Math.ceil(rz); dz <= Math.ceil(rz); dz++) {
        for (let dx = -Math.ceil(rx); dx <= Math.ceil(rx); dx++) {
          const distNorm = (dx * dx) / rx2 + (dy * dy) / ry2 + (dz * dz) / rz2;
          if (distNorm <= 1.0) {
            const px = cx + dx;
            const py = cy + dy;
            const pz = cz + dz;
            if (py >= 0 && py < H && px >= 0 && px < W && pz >= 0 && pz < D) {
              if (getBlock(px, py, pz) === 0) {
                setBlock(px, py, pz, leaves);
              }
            }
          }
        }
      }
    }
  }

  // Central Crown Umbrella
  drawFoliagePad(32, 49, 32, 10.0, 2.2, 10.0);

  // Bough Tip Foliage Pads
  const leafPads = [
    { x: 52, y: 41, z: 16, rx: 6.0, ry: 1.8, rz: 6.0 },
    { x: 58, y: 44, z: 20, rx: 5.0, ry: 1.6, rz: 5.0 },
    { x: 48, y: 46, z: 10, rx: 4.8, ry: 1.5, rz: 4.8 },

    { x: 53, y: 39, z: 50, rx: 6.0, ry: 1.8, rz: 6.0 },
    { x: 57, y: 42, z: 44, rx: 5.0, ry: 1.6, rz: 5.0 },
    { x: 50, y: 44, z: 56, rx: 4.8, ry: 1.5, rz: 4.8 },

    { x: 13, y: 40, z: 50, rx: 6.0, ry: 1.8, rz: 6.0 },
    { x: 10, y: 44, z: 44, rx: 5.0, ry: 1.6, rz: 5.0 },
    { x: 16, y: 45, z: 57, rx: 4.8, ry: 1.5, rz: 4.8 },

    { x: 12, y: 39, z: 14, rx: 6.0, ry: 1.8, rz: 6.0 },
    { x: 10, y: 43, z: 22, rx: 5.0, ry: 1.6, rz: 5.0 },
    { x: 16, y: 44, z: 8, rx: 4.8, ry: 1.5, rz: 4.8 },
  ];
  for (const pad of leafPads) {
    drawFoliagePad(pad.x, pad.y, pad.z, pad.rx, pad.ry, pad.rz);
  }

  // -------------------------------------------------------------------------
  // 7. Treehouse Platforms & Hanging Village Decks
  // -------------------------------------------------------------------------
  // Helper for circular wooden deck
  function drawDeck(cx, cy, cz, rad) {
    const rad2 = rad * rad;
    for (let dz = -Math.ceil(rad); dz <= Math.ceil(rad); dz++) {
      for (let dx = -Math.ceil(rad); dx <= Math.ceil(rad); dx++) {
        const d2 = dx * dx + dz * dz;
        if (d2 <= rad2) {
          const px = cx + dx;
          const pz = cz + dz;
          setBlock(px, cy, pz, woodPlanks);
          for (let y = cy + 1; y <= cy + 4; y++) {
            clearBlock(px, y, pz);
          }
          if (d2 > (rad - 1.1) * (rad - 1.1)) {
            setBlock(px, cy + 1, pz, woodFence);
          }
        }
      }
    }
  }

  // Platform 1: North-East Village House (center (49, 41, 18))
  drawDeck(49, 41, 18, 4.5);
  // House walls & Roof
  for (let y = 42; y <= 45; y++) {
    setBlock(47, y, 16, woodLog);
    setBlock(51, y, 16, woodLog);
    setBlock(51, y, 20, woodLog);
    setBlock(47, y, 20, woodLog);
  }
  // Roof
  for (let x = 46; x <= 52; x++) {
    setBlock(x, 46, 15, stair(cleanRoofStairs, "south", "bottom"));
    setBlock(x, 46, 21, stair(cleanRoofStairs, "north", "bottom"));
    setBlock(x, 47, 16, stair(cleanRoofStairs, "south", "bottom"));
    setBlock(x, 47, 20, stair(cleanRoofStairs, "north", "bottom"));
    setBlock(x, 47, 17, slab(cleanRoofSlab, "top"));
    setBlock(x, 47, 18, slab(cleanRoofSlab, "top"));
    setBlock(x, 47, 19, slab(cleanRoofSlab, "top"));
  }
  setBlock(49, 45, 18, lanternHang);

  // Platform 2: South-West Lookout Deck (center (15, 40, 48))
  drawDeck(15, 40, 48, 4.2);
  // Gazebo Awning
  for (let y = 41; y <= 43; y++) {
    setBlock(13, y, 46, woodFence);
    setBlock(17, y, 46, woodFence);
    setBlock(17, y, 50, woodFence);
    setBlock(13, y, 50, woodFence);
  }
  for (let x = 12; x <= 18; x++) {
    for (let z = 45; z <= 51; z++) {
      if (Math.abs(x - 15) <= 2 && Math.abs(z - 48) <= 2) {
        setBlock(x, 44, z, slab(cleanRoofSlab, "bottom"));
      }
    }
  }
  setBlock(15, 43, 48, lanternHang);

  // Platform 3: South-East Cargo Hoist Platform (center (50, 38, 48))
  drawDeck(50, 38, 48, 3.8);
  // Crane boom
  for (let y = 39; y <= 44; y++) {
    setBlock(50, y, 46, woodLog);
  }
  setBlock(51, 44, 47, woodFence);
  setBlock(52, 45, 48, woodFence);
  setBlock(53, 45, 49, woodFence);
  setBlock(54, 45, 50, woodFence);
  setBlock(54, 44, 50, chain);
  setBlock(54, 43, 50, chain);
  setBlock(54, 42, 50, woodPlanks);

  // -------------------------------------------------------------------------
  // 8. Suspension Rope Bridges
  // -------------------------------------------------------------------------
  function drawRopeBridge(p0, p1, sag) {
    const steps = 18;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const x = Math.round((1 - t) * p0[0] + t * p1[0]);
      const z = Math.round((1 - t) * p0[2] + t * p1[2]);
      const parabola = 4 * sag * t * (1 - t);
      const y = Math.round((1 - t) * p0[1] + t * p1[1] - parabola);

      setBlock(x, y, z, slab(cleanWoodSlab, "bottom"));
      clearBlock(x, y + 1, z);
      clearBlock(x, y + 2, z);

      // Handrails
      const dx = p1[0] - p0[0];
      const dz = p1[2] - p0[2];
      const len = Math.sqrt(dx * dx + dz * dz);
      const nx = Math.round(-dz / len);
      const nz = Math.round(dx / len);

      setBlock(x + nx, y + 1, z + nz, woodFence);
      setBlock(x - nx, y + 1, z - nz, woodFence);
    }
  }

  // Bridge 1: Trunk High Balcony -> NE Platform
  drawRopeBridge([36, 35, 26], [45, 41, 18], 1.5);

  // Bridge 2: Trunk West Balcony -> SW Platform
  drawRopeBridge([25, 34, 36], [18, 40, 45], 1.5);

  // Bridge 3: SW Platform -> SE Platform
  drawRopeBridge([18, 40, 50], [46, 38, 50], 2.2);

  // -------------------------------------------------------------------------
  // 9. Hanging Lantern Clusters under Boughs
  // -------------------------------------------------------------------------
  const lanternChains = [
    { x: 44, yTop: 36, yBot: 32, z: 24 },
    { x: 46, yTop: 35, yBot: 30, z: 42 },
    { x: 20, yTop: 36, yBot: 31, z: 43 },
    { x: 20, yTop: 35, yBot: 30, z: 22 },
    { x: 32, yTop: 33, yBot: 27, z: 43 },
  ];
  for (const lc of lanternChains) {
    for (let y = lc.yTop; y > lc.yBot; y--) {
      setBlock(lc.x, y, lc.z, chain);
    }
    setBlock(lc.x, lc.yBot, lc.z, lanternHang);
  }

  // -------------------------------------------------------------------------
  // 10. Flush Buffer to api.set
  // -------------------------------------------------------------------------
  for (let z = 0; z < D; z++) {
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const id = grid[x + y * W + z * W * H];
        if (id > 0) {
          api.set(x, y, z, palette[id]);
        }
      }
    }
  }

  return {
    name: "colossal_baobab",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
      door: [cx, seatY, cz - 14],
      market: [cx, seatY, cz],
    },
    interiors: [
      {
        min: [cx - 8, seatY + 1, cz - 8],
        max: [cx + 8, seatY + 6, cz + 8],
        kind: "hall",
      },
      {
        min: [cx - 7, 19, cz - 7],
        max: [cx + 7, 24, cz + 7],
        kind: "quarters",
      },
      {
        min: [cx - 2, 27, cz - 6],
        max: [cx + 2, 31, cz + 6],
        kind: "bridge",
      },
      {
        min: [47, 42, 16],
        max: [51, 45, 20],
        kind: "quarters",
      },
      {
        min: [13, 41, 46],
        max: [17, 43, 50],
        kind: "quarters",
      },
    ],
  };
}

