export const envelope = [13, 14, 13];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;
  const deckY = 4;
  const inst = api.instance.index % 6;

  // --- Theme Resolution ---
  function getBlock(val, fallback) {
    return typeof val === "string" && val.length > 0 ? val : fallback;
  }

  const woodPlanks = getBlock(api.theme?.wood?.planks, "minecraft:acacia_planks");
  const woodLog = getBlock(api.theme?.wood?.log, "minecraft:acacia_log");
  const woodStripped = getBlock(api.theme?.wood?.stripped, "minecraft:stripped_acacia_log");
  const woodStairs = getBlock(api.theme?.wood?.stairs, "minecraft:acacia_stairs");
  const woodSlab = getBlock(api.theme?.wood?.slab, "minecraft:acacia_slab");
  const woodFence = getBlock(api.theme?.wood?.fence, "minecraft:acacia_fence");
  const woodTrapdoor = getBlock(api.theme?.wood?.trapdoor, "minecraft:acacia_trapdoor");
  const woodDoor = getBlock(api.theme?.wood?.door, "minecraft:acacia_door");
  const roofSolid = getBlock(api.theme?.roof?.solid, "minecraft:hay_block");
  const roofStairs = getBlock(api.theme?.roof?.stairs, "minecraft:acacia_stairs");
  const roofSlab = getBlock(api.theme?.roof?.slab, "minecraft:acacia_slab");
  const stoneWall = getBlock(api.theme?.stone?.wall, "minecraft:cobblestone_wall");

  // Helper block state builders
  function logAxis(baseLog, axis = "y") {
    const base = baseLog.split("[")[0];
    return `${base}[axis=${axis}]`;
  }

  function stair(baseStair, facing = "north", half = "bottom", shape = "straight") {
    const base = baseStair.split("[")[0];
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function slab(baseSlab, type = "bottom") {
    const base = baseSlab.split("[")[0];
    return `${base}[type=${type}]`;
  }

  function trapdoor(baseTrap, facing = "north", half = "bottom", open = false) {
    const base = baseTrap.split("[")[0];
    return `${base}[facing=${facing},half=${half},open=${open}]`;
  }

  function door(baseDoor, facing = "north", half = "lower", hinge = "left", open = false) {
    const base = baseDoor.split("[")[0];
    return `${base}[facing=${facing},half=${half},hinge=${hinge},open=${open}]`;
  }

  const leaves = "minecraft:acacia_leaves[distance=1,persistent=true]";
  const lanternHang = "minecraft:lantern[hanging=true]";
  const lanternFloor = "minecraft:lantern[hanging=false]";
  const chainY = "minecraft:chain[axis=y]";

  // Grid buffer for deterministic writes and in-bounds safety
  const world = new Map();
  function setBlock(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    world.set(`${x},${y},${z}`, block);
  }

  function getBlockAt(x, y, z) {
    return world.get(`${x},${y},${z}`);
  }

  // --- Per-instance Variation Configuration ---
  // 1. Colossal baobab bough corner
  const boughConfigs = [
    { bx: [8, 9], bz: [8, 9], leanX: 1, leanZ: 1 },    // 0: SE
    { bx: [3, 4], bz: [8, 9], leanX: -1, leanZ: 1 },   // 1: SW
    { bx: [8, 9], bz: [3, 4], leanX: 1, leanZ: -1 },   // 2: NE
    { bx: [3, 4], bz: [3, 4], leanX: -1, leanZ: -1 },  // 3: NW
    { bx: [2, 3], bz: [5, 6], leanX: -1, leanZ: 0 },   // 4: W
    { bx: [9, 10], bz: [5, 6], leanX: 1, leanZ: 0 }    // 5: E
  ];
  const bough = boughConfigs[inst];

  // 2. Rope bridge exits
  // North bridge stub is standard front exit; lateral exits vary per instance
  const hasNorthBridge = true;
  const hasEastBridge = inst === 1 || inst === 2 || inst === 5;
  const hasWestBridge = inst === 0 || inst === 4;
  const hasSouthBridge = inst === 3;

  // 3. Hut bounds & Layout
  let hutX1 = 3, hutX2 = 7;
  let hutZ1 = 4, hutZ2 = 8;
  if (inst === 4) {
    hutX1 = 5; hutX2 = 9;
  } else if (inst === 5) {
    hutX1 = 3; hutX2 = 7;
  }

  const doorX = Math.floor((hutX1 + hutX2) / 2);
  const doorZ = hutZ1;

  // --- 1. STILTS & TERRAIN CONFORMITY ---
  const stiltColumns = [
    [3, 3], [9, 3], [3, 9], [9, 9],
    [6, 3], [6, 9], [3, 6], [9, 6]
  ];

  for (const [sx, sz] of stiltColumns) {
    // Skip if covered by colossal bough
    const inBough = sx >= bough.bx[0] && sx <= bough.bx[1] && sz >= bough.bz[0] && sz <= bough.bz[1];
    if (inBough) continue;

    const terrainH = Math.round(api.heightAt(sx, sz));
    const startY = Math.max(0, Math.min(deckY - 1, seatY + terrainH));

    for (let y = startY; y < deckY; y++) {
      setBlock(sx, y, sz, logAxis(woodLog, "y"));
    }
    // Masonry footing collar if ground is below seat
    if (startY > 0 && startY < seatY) {
      setBlock(sx, startY, sz, stoneWall);
    }
    // Diagonal brace struts under deck
    if (deckY - 1 >= startY) {
      if (sx === 3) setBlock(sx + 1, deckY - 1, sz, stair(woodStairs, "east", "top"));
      if (sx === 9) setBlock(sx - 1, deckY - 1, sz, stair(woodStairs, "west", "top"));
      if (sz === 3) setBlock(sx, deckY - 1, sz + 1, stair(woodStairs, "south", "top"));
      if (sz === 9) setBlock(sx, deckY - 1, sz - 1, stair(woodStairs, "north", "top"));
    }
  }

  // Exterior Access Ladder on front-west stilt
  const ladderX = 3, ladderZ = 3;
  const ladderTerrain = Math.max(0, Math.min(deckY - 1, seatY + Math.round(api.heightAt(ladderX, ladderZ))));
  for (let y = ladderTerrain + 1; y < deckY; y++) {
    setBlock(ladderX, y, ladderZ - 1, "minecraft:ladder[facing=north]");
  }

  // --- 2. COLOSSAL BAOBAB BOUGH ---
  for (let bx = bough.bx[0]; bx <= bough.bx[1]; bx++) {
    for (let bz = bough.bz[0]; bz <= bough.bz[1]; bz++) {
      const boughTerrain = Math.max(0, Math.min(deckY, seatY + Math.round(api.heightAt(bx, bz))));
      // Trunk rising from ground up to canopy
      for (let y = boughTerrain; y <= deckY + 4; y++) {
        setBlock(bx, y, bz, logAxis(woodStripped, "y"));
      }
      // Top branch head tilting outwards
      const topY = deckY + 5;
      setBlock(bx + bough.leanX, topY, bz + bough.leanZ, logAxis(woodStripped, "y"));
      setBlock(bx + bough.leanX, topY + 1, bz + bough.leanZ, logAxis(woodLog, "y"));
    }
  }

  // Canopy branch horizontal arms & leaves
  const branchCenterY = deckY + 6;
  const branchCenterX = Math.floor((bough.bx[0] + bough.bx[1]) / 2) + bough.leanX;
  const branchCenterZ = Math.floor((bough.bz[0] + bough.bz[1]) / 2) + bough.leanZ;

  // Horizontal branch struts
  for (let d = 1; d <= 2; d++) {
    setBlock(branchCenterX + d, branchCenterY, branchCenterZ, logAxis(woodLog, "x"));
    setBlock(branchCenterX - d, branchCenterY, branchCenterZ, logAxis(woodLog, "x"));
    setBlock(branchCenterX, branchCenterY, branchCenterZ + d, logAxis(woodLog, "z"));
    setBlock(branchCenterX, branchCenterY, branchCenterZ - d, logAxis(woodLog, "z"));
  }

  // Lush acacia foliage cluster attached to canopy branches
  for (let ox = -2; ox <= 2; ox++) {
    for (let oz = -2; oz <= 2; oz++) {
      for (let oy = -1; oy <= 2; oy++) {
        const lx = branchCenterX + ox;
        const ly = branchCenterY + oy;
        const lz = branchCenterZ + oz;
        const distSq = ox * ox + oz * oz + oy * oy * 1.5;
        if (distSq <= 6.5) {
          if (!getBlockAt(lx, ly, lz)) {
            setBlock(lx, ly, lz, leaves);
          }
        }
      }
    }
  }

  // --- 3. TIMBER PLATFORM DECK ---
  for (let x = 2; x <= 10; x++) {
    for (let z = 2; z <= 10; z++) {
      // Chamfer 4 corners for octagonal platform profile
      if ((x === 2 && z === 2) || (x === 10 && z === 2) || (x === 2 && z === 10) || (x === 10 && z === 10)) {
        continue;
      }

      // Deck perimeter beams vs inner floor
      const isPerimeter = (x === 2 || x === 10 || z === 2 || z === 10 ||
        (x === 3 && (z === 2 || z === 10)) || (x === 9 && (z === 2 || z === 10)) ||
        (z === 3 && (x === 2 || x === 10)) || (z === 9 && (x === 2 || x === 10)));

      if (!getBlockAt(x, deckY, z)) {
        setBlock(x, deckY, z, isPerimeter ? woodStripped : woodPlanks);
      }
    }
  }

  // Trapdoor over ladder opening
  setBlock(ladderX, deckY, ladderZ - 1, trapdoor(woodTrapdoor, "north", "bottom", false));

  // Deck Perimeter Railing
  for (let x = 2; x <= 10; x++) {
    for (let z = 2; z <= 10; z++) {
      if ((x === 2 && z === 2) || (x === 10 && z === 2) || (x === 2 && z === 10) || (x === 10 && z === 10)) continue;

      const isEdge = (x === 2 || x === 10 || z === 2 || z === 10);
      if (!isEdge) continue;

      // Check for bridge and ladder gaps
      if (hasNorthBridge && z === 2 && (x >= 5 && x <= 7)) continue;
      if (hasSouthBridge && z === 10 && (x >= 5 && x <= 7)) continue;
      if (hasWestBridge && x === 2 && (z >= 5 && z <= 7)) continue;
      if (hasEastBridge && x === 10 && (z >= 5 && z <= 7)) continue;
      if (x === ladderX && z === 2) continue;

      // Do not place fence over the bough trunk
      if (x >= bough.bx[0] && x <= bough.bx[1] && z >= bough.bz[0] && z <= bough.bz[1]) continue;

      setBlock(x, deckY + 1, z, woodFence);
    }
  }

  // --- 4. ROPE BRIDGE STUBS ---
  // North Bridge Stub (extends toward z = 0)
  if (hasNorthBridge) {
    for (let z = 1; z >= 0; z--) {
      setBlock(6, deckY, z, slab(woodSlab, "bottom"));
      setBlock(5, deckY + 1, z, woodFence);
      setBlock(7, deckY + 1, z, woodFence);
    }
    // Bridge entry posts & hanging lanterns
    setBlock(5, deckY + 2, 0, woodFence);
    setBlock(7, deckY + 2, 0, woodFence);
    setBlock(5, deckY + 3, 0, lanternFloor);
  }

  // South Bridge Stub (extends toward z = 12)
  if (hasSouthBridge) {
    for (let z = 11; z <= 12; z++) {
      setBlock(6, deckY, z, slab(woodSlab, "bottom"));
      setBlock(5, deckY + 1, z, woodFence);
      setBlock(7, deckY + 1, z, woodFence);
    }
    setBlock(5, deckY + 2, 12, woodFence);
    setBlock(7, deckY + 2, 12, woodFence);
    setBlock(7, deckY + 3, 12, lanternFloor);
  }

  // East Bridge Stub (extends toward x = 12)
  if (hasEastBridge) {
    for (let x = 11; x <= 12; x++) {
      setBlock(x, deckY, 6, slab(woodSlab, "bottom"));
      setBlock(x, deckY + 1, 5, woodFence);
      setBlock(x, deckY + 1, 7, woodFence);
    }
    setBlock(12, deckY + 2, 5, woodFence);
    setBlock(12, deckY + 2, 7, woodFence);
    setBlock(12, deckY + 3, 5, lanternFloor);
  }

  // West Bridge Stub (extends toward x = 0)
  if (hasWestBridge) {
    for (let x = 1; x >= 0; x--) {
      setBlock(x, deckY, 6, slab(woodSlab, "bottom"));
      setBlock(x, deckY + 1, 5, woodFence);
      setBlock(x, deckY + 1, 7, woodFence);
    }
    setBlock(0, deckY + 2, 5, woodFence);
    setBlock(0, deckY + 2, 7, woodFence);
    setBlock(0, deckY + 3, 7, lanternFloor);
  }

  // --- 5. TIMBER PLATFORM HUT WALLS ---
  const wallTopY = deckY + 3; // y = 7

  for (let x = hutX1; x <= hutX2; x++) {
    for (let z = hutZ1; z <= hutZ2; z++) {
      const isWall = (x === hutX1 || x === hutX2 || z === hutZ1 || z === hutZ2);
      if (!isWall) continue;

      const isCorner = (x === hutX1 || x === hutX2) && (z === hutZ1 || z === hutZ2);

      for (let y = deckY + 1; y <= wallTopY; y++) {
        if (isCorner) {
          setBlock(x, y, z, logAxis(woodStripped, "y"));
        } else {
          // Doorway on front wall
          if (z === doorZ && x === doorX) {
            if (y === deckY + 1) setBlock(x, y, z, door(woodDoor, "north", "lower", "left", false));
            else if (y === deckY + 2) setBlock(x, y, z, door(woodDoor, "north", "upper", "left", false));
            else setBlock(x, y, z, woodStripped);
          }
          // Window openings with wooden fences / shutters
          else if (y === deckY + 2 && ((x === hutX1 || x === hutX2) && z === Math.floor((hutZ1 + hutZ2) / 2))) {
            setBlock(x, y, z, woodFence);
          } else if (y === deckY + 2 && (z === hutZ2 && x === Math.floor((hutX1 + hutX2) / 2))) {
            setBlock(x, y, z, woodFence);
          } else {
            setBlock(x, y, z, woodPlanks);
          }
        }
      }
    }
  }

  // --- 6. CURVED THATCH AWNING & ROOF ---
  const roofStyle = inst % 3; // 0: Curved Barrel Awning, 1: Sloped Shed Awning, 2: Thatched Pavilion

  if (roofStyle === 0) {
    // Style 0: Arched Thatch Awning over hut and terrace
    const rx1 = hutX1 - 1;
    const rx2 = hutX2 + 1;
    const rz1 = hutZ1 - 1;
    const rz2 = hutZ2 + 1;

    // Eaves course at y = 8
    for (let z = rz1; z <= rz2; z++) {
      setBlock(rx1, 8, z, stair(roofStairs, "east", "bottom"));
      setBlock(rx2, 8, z, stair(roofStairs, "west", "bottom"));
      for (let x = rx1 + 1; x <= rx2 - 1; x++) {
        setBlock(x, 8, z, roofSolid);
      }
    }

    // Mid course at y = 9
    for (let z = rz1; z <= rz2; z++) {
      setBlock(rx1 + 1, 9, z, stair(roofStairs, "east", "bottom"));
      setBlock(rx2 - 1, 9, z, stair(roofStairs, "west", "bottom"));
      for (let x = rx1 + 2; x <= rx2 - 2; x++) {
        setBlock(x, 9, z, roofSolid);
      }
    }

    // Ridge peak at y = 10
    const midX = Math.floor((rx1 + rx2) / 2);
    for (let z = rz1; z <= rz2; z++) {
      setBlock(midX, 10, z, slab(roofSlab, "bottom"));
    }

    // Lantern hanging from front awning peak
    setBlock(midX, 9, rz1, chainY);
    setBlock(midX, 8, rz1, lanternHang);

  } else if (roofStyle === 1) {
    // Style 1: Asymmetrical Sloped Shed Awning leaning forward over terrace
    const rx1 = hutX1 - 1;
    const rx2 = hutX2 + 1;
    const rz1 = hutZ1 - 1;
    const rz2 = hutZ2 + 1;

    for (let x = rx1; x <= rx2; x++) {
      setBlock(x, 8, rz1, stair(roofStairs, "north", "bottom"));
      setBlock(x, 8, rz1 + 1, roofSolid);
      setBlock(x, 9, rz1 + 2, stair(roofStairs, "north", "bottom"));
      setBlock(x, 9, rz1 + 3, roofSolid);
      setBlock(x, 10, rz2 - 1, stair(roofStairs, "north", "bottom"));
      setBlock(x, 10, rz2, roofSolid);
      setBlock(x, 11, rz2, slab(roofSlab, "bottom"));
    }

    // Front valance trapdoors
    for (let x = rx1; x <= rx2; x++) {
      setBlock(x, 7, rz1, trapdoor(woodTrapdoor, "north", "top", false));
    }

    // Hanging lantern at front corner
    setBlock(rx1, 7, rz1, chainY);
    setBlock(rx1, 6, rz1, lanternHang);

  } else {
    // Style 2: Thatched Pavilion / Hip Roof with spire
    const rx1 = hutX1 - 1;
    const rx2 = hutX2 + 1;
    const rz1 = hutZ1 - 1;
    const rz2 = hutZ2 + 1;

    // Base tier y = 8
    for (let x = rx1; x <= rx2; x++) {
      for (let z = rz1; z <= rz2; z++) {
        const isBorder = (x === rx1 || x === rx2 || z === rz1 || z === rz2);
        if (isBorder) {
          if (z === rz1) setBlock(x, 8, z, stair(roofStairs, "south", "bottom"));
          else if (z === rz2) setBlock(x, 8, z, stair(roofStairs, "north", "bottom"));
          else if (x === rx1) setBlock(x, 8, z, stair(roofStairs, "east", "bottom"));
          else if (x === rx2) setBlock(x, 8, z, stair(roofStairs, "west", "bottom"));
        } else {
          setBlock(x, 8, z, roofSolid);
        }
      }
    }

    // Mid tier y = 9
    for (let x = rx1 + 1; x <= rx2 - 1; x++) {
      for (let z = rz1 + 1; z <= rz2 - 1; z++) {
        const isBorder = (x === rx1 + 1 || x === rx2 - 1 || z === rz1 + 1 || z === rz2 - 1);
        if (isBorder) {
          if (z === rz1 + 1) setBlock(x, 9, z, stair(roofStairs, "south", "bottom"));
          else if (z === rz2 - 1) setBlock(x, 9, z, stair(roofStairs, "north", "bottom"));
          else if (x === rx1 + 1) setBlock(x, 9, z, stair(roofStairs, "east", "bottom"));
          else if (x === rx2 - 1) setBlock(x, 9, z, stair(roofStairs, "west", "bottom"));
        } else {
          setBlock(x, 9, z, roofSolid);
        }
      }
    }

    // Top tier y = 10 and finial
    const midX = Math.floor((rx1 + rx2) / 2);
    const midZ = Math.floor((rz1 + rz2) / 2);
    setBlock(midX, 10, midZ, roofSolid);
    setBlock(midX, 11, midZ, woodFence);
    setBlock(midX, 12, midZ, lanternFloor);
  }

  // --- 7. CARGO WINCH / CRANE PROP ---
  // A timber crane perched on an open terrace corner for lifting village goods
  const craneX = (hutX1 >= 4) ? 2 : 10;
  const craneZ = 3;
  setBlock(craneX, deckY + 1, craneZ, woodFence);
  setBlock(craneX, deckY + 2, craneZ, woodFence);
  setBlock(craneX, deckY + 3, craneZ, logAxis(woodStripped, "z"));
  setBlock(craneX, deckY + 3, craneZ - 1, stair(woodStairs, "south", "top"));
  setBlock(craneX, deckY + 2, craneZ - 1, chainY);
  setBlock(craneX, deckY + 1, craneZ - 1, "minecraft:barrel[facing=up]");

  // --- 8. EMIT BLOCKS DETERMINISTICALLY ---
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const blk = world.get(`${x},${y},${z}`);
        if (blk) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  // Declare spacious 3x3x3 interior room inside hut for compiler fit-out
  const interiorMinX = hutX1 + 1;
  const interiorMaxX = hutX2 - 1;
  const interiorMinZ = hutZ1 + 1;
  const interiorMaxZ = hutZ2 - 1;

  return {
    name: "canopy_platform_house",
    seatY: seatY,
    anchors: {
      front: [6, deckY + 1, 0],
      door: [doorX, deckY + 1, doorZ]
    },
    interiors: [
      {
        min: [interiorMinX, deckY + 1, interiorMinZ],
        max: [interiorMaxX, deckY + 3, interiorMaxZ],
        kind: "quarters"
      }
    ]
  };
}
